// Development oracle: packed PABCSystem fields and public BinaryReader/BinaryWriter.
using System;using System.IO;using System.Text;using System.Globalization;
class BinaryFileReference{
 static string Hex(byte[] bytes){return bytes.Length==0?"-":BitConverter.ToString(bytes).Replace("-","").ToLowerInvariant();}
 static void Main(string[] args){BinaryOracle.Setup(args.Length>2&&args[2]=="modern");int rows=0;using(var log=new StreamWriter(args[1],false,new UTF8Encoding(false))){log.WriteLine("# code_page\tIsSingleByte\tpacked_bytes\tread_char_units");foreach(var line in File.ReadAllLines(args[0])){if(line.Length==0||line[0]=='#')continue;var fields=line.Split('\t');int cp=int.Parse(fields[0],CultureInfo.InvariantCulture);var e=BinaryOracle.Get(cp);if(!e.IsSingleByte){log.WriteLine(cp+"\tFalse\t-\t-");++rows;continue;}byte[] bytes;using(var memory=new MemoryStream()){var writer=new BinaryWriter(memory,e);for(int i=0;i<9;++i){writer.Write(i%2==1);writer.Write((byte)(i*31));writer.Write((sbyte)(i-4));writer.Write((ushort)(65535-i*157));writer.Write((short)(-32768+i*971));writer.Write(int.MinValue+i*1234567);writer.Write(uint.MaxValue-(uint)i*33331);writer.Write(-9223372036854775807L+(long)i*123456789);writer.Write(ulong.MaxValue-(ulong)i*54321987);writer.Write((float)(i+0.25));writer.Write(i+0.125);writer.Write((char)(i*997));writer.Write(i%3);writer.Write(999-i);writer.Write((char)(i*991+63));}bytes=memory.ToArray();}
 var units=new StringBuilder();using(var memory=new MemoryStream(bytes)){var reader=new BinaryReader(memory,e);for(int i=0;i<9;++i){reader.ReadBoolean();reader.ReadByte();reader.ReadSByte();reader.ReadUInt16();reader.ReadInt16();reader.ReadInt32();reader.ReadUInt32();reader.ReadInt64();reader.ReadUInt64();reader.ReadSingle();reader.ReadDouble();if(i>0)units.Append(',');units.Append(((int)reader.ReadChar()).ToString("x4"));reader.ReadInt32();reader.ReadInt32();units.Append(',').Append(((int)reader.ReadChar()).ToString("x4"));}}log.WriteLine(cp+"\tTrue\t"+Hex(bytes)+"\t"+units);++rows;}}Console.WriteLine(rows+" packed typed-file reference rows");}
}
